  function newNode(type,graph,point){let index=1,id;do{id=type+'-'+index++;}while(graph.nodes.some(n=>n.id===id));const count=graph.nodes.filter(n=>n.type===type).length;return{id,type,x:Math.max(12,Math.round(point?.x??(280+count*55))),y:Math.max(35,Math.round(point?.y??(90+graph.nodes.length*55))),enabled:true,config:{name:definitions[type].name+(count?' '+(count+1):''),...(type==='summary'?{interval_seconds:60,prompt:'Describe the current scene and any notable activity.'}:{}),...(type==='events'?{features:[],event_sensitivities:{}}:{})}};}
