    get draft(){if(!this.workflow)return null;if(!this.drafts.has(this.workflow.id))this.drafts.set(this.workflow.id,{name:this.workflow.name,graph:graphOf(this.workflow.graph)});return this.drafts.get(this.workflow.id);}
