    dirty(id=this.workflowId){const draft=this.drafts.get(id),saved=this.workflows.find(w=>w.id===id);return Boolean(draft&&saved&&JSON.stringify(draft)!==JSON.stringify({name:saved.name,graph:graphOf(saved.graph)}));}
    needsApply(id=this.workflowId){const saved=this.workflows.find(workflow=>workflow.id===id);return this.dirty(id)||this.assignedGroups(id).some(group=>JSON.stringify(group.applied_graph)!==JSON.stringify(saved?.graph));}
