        if(target.matches('[data-wc-apply-group]')){if(this.assignedGroups().some(group=>group.id===target.dataset.wcApplyGroup)){target.checked=true;return;}const selected=new Set(this.dialog?.groups||[]);target.checked?selected.add(target.dataset.wcApplyGroup):selected.delete(target.dataset.wcApplyGroup);this.dialog.groups=[...selected];this.renderPreservingFocus(target);return;}
